insert into plataformas (slug,nombre,estado,etiqueta_descarte,motivo_descarte,verificada_el) values ('toucan-protocol','Toucan Protocol','descartada','Registro bloqueado en 2022','En mayo de 2022, Verra prohibió tokenizar créditos ya retirados y el American Carbon Registry prohibió tokenizar los suyos sin su autorización expresa. Hoy Toucan solo tokeniza créditos del registro Puro (su cesta CHAR, de biocarbón), con los créditos inmovilizados en ese registro. No la hemos vuelto a evaluar para el radar.','2026-08-06');
